/* UV2 — banque de questions types (mêmes thèmes que le dossier d’évaluation, autres valeurs ou autres cas).
   Elle alimente les UV2 blancs de 60 questions (10 par matière) avec les questions du dossier et leurs variantes. */
(function () {
  function lesson(id, title, retenir, cle, points, astuce) {
    return { id: id, title: title, html: '<p>Questions du même type que l’épreuve UV2 : 3 propositions, une seule bonne réponse. Barème : bonne réponse + 1, mauvaise − 0,5, pas de réponse 0.</p>', retenir: retenir, pieges: ['Si tu hésites entre les 3 propositions, ne réponds pas : une erreur retire 0,5 point.'], memo: { cle: cle, points: points, astuce: astuce } };
  }
  var L = 'uv2-banque', D = 'dsft/', B = 'livres/', Y = 'sym/', G = 'gd22/', A = 'aga01/', E = 'elec/';

  /* ======================= DSFT ======================= */
  REV.addExercises('dsft', {
    lessons: [lesson(L, 'UV2 — Questions types : DSFT', ['Écrire la plage mini–maxi avant de comparer (1° = 60′).', 'Angle inclus = inclinaison de pivot + 90° + carrossage : bon → triangle, berceau ou châssis ; pas bon → fusée, porte-fusée et/ou jambe de force.', 'Tire du côté du carrossage le plus positif et de la chasse la plus faible.', 'Rugueuse = parallélisme ; lisse = carrossage ; facettes = amortisseurs.'], 'PLAGE · ANGLE INCLUS · USURE', ['Parallélisme réglé en dernier', 'Willis : Zp·Np + Zc·Nc = (Zp + Zc)·Nps', 'Liquide < 165 °C = à remplacer'], 'Lis toujours le tableau ligne par ligne, G puis D.')],
    questions: [
      { l: L, img: D + 'alfa-b.svg', q: 'D’après ce tableau ALFA, quels angles sont hors tolérance ?', c: ['Le parallélisme, le carrossage droit et le pivot droit.', 'Le carrossage droit et la chasse gauche.', 'Le parallélisme, le carrossage gauche et le pivot gauche.'], e: 'Parallélisme : plage 0 à +2 mm, relevé −1 mm (ouverture) → hors. Carrossage : plage −0°30′ à +0°30′ → D +0°45′ hors. Chasse : 2°00′ à 3°00′ → bonne. Pivot : 9°00′ à 10°00′ → D 8°50′ hors.' },
      { l: L, img: D + 'alfa-b.svg', q: 'D’après ce tableau ALFA, quelle pièce pouvez-vous incriminer ?', c: ['Un triangle.', 'La fusée / porte-fusée.', 'La barre de direction.'], e: 'Angle inclus G = 9°40′ + 0°10′ = 9°50′ ; D = 8°50′ + 0°45′ = 9°35′ : presque identiques → la fusée est bonne, c’est la position du pivot qui a bougé → triangle.' },
      { l: L, img: D + 'alfa-b.svg', q: 'D’après ce tableau ALFA, le véhicule aura-t-il tendance à tirer ?', c: ['Oui, il tirera à droite.', 'Non, il ne tirera pas.', 'Oui, il tirera à gauche.'], e: 'Carrossage le plus positif à droite (+0°45′) et chasse la plus faible à droite (2°40′) → il tire à droite.' },
      { l: L, img: D + 'alfa-b.svg', q: 'Pour corriger la VALEUR du parallélisme relevé dans ce tableau, on agit sur :', c: ['La barre d’accouplement.', 'La barre de direction.', 'Le boîtier de direction.'], e: 'Barre d’accouplement = valeur du parallélisme ; barre de direction = répartition G/D (volant bloqué, repères alignés).' },
      { l: L, img: D + 'alfa-c.svg', q: 'D’après ce tableau ALFA, quels angles sont hors tolérance ?', c: ['Uniquement le carrossage droit.', 'Le carrossage droit et le pivot droit.', 'Le parallélisme et le carrossage droit.'], e: 'Carrossage : plage −0°10′ à +0°50′ → D −0°40′ hors. Parallélisme (−1 à +1 mm), chasse (2°30′ à 3°30′) et pivot (10°30′ à 11°30′) sont bons.' },
      { l: L, img: D + 'alfa-c.svg', q: 'D’après ce tableau ALFA, quelle pièce pouvez-vous incriminer ?', c: ['La fusée, le porte-fusée et/ou la jambe de force.', 'Un triangle.', 'La barre d’accouplement.'], e: 'Angle inclus G = 11°05′ + 0°25′ = 11°30′ ; D = 11°10′ − 0°40′ = 10°30′ : 1° d’écart → angle inclus pas bon : fusée, porte-fusée et/ou jambe de force (côté droit).' },
      { l: L, img: D + 'alfa-c.svg', q: 'D’après ce tableau ALFA, le véhicule aura-t-il tendance à tirer ?', c: ['Oui, il tirera à gauche.', 'Oui, il tirera à droite.', 'Non, il ne tirera pas.'], e: 'Carrossage le plus positif à gauche (+0°25′) et chasse la plus faible à gauche (3°05′) → il tire à gauche.' },
      { l: L, img: D + 'alfa-c.svg', q: 'Avec ces relevés, quelle usure allez-vous trouver sur le pneu avant droit ?', c: ['Une usure lisse côté intérieur.', 'Une usure rugueuse côté extérieur.', 'Une usure en facettes.'], e: 'Carrossage faux = usure lisse ; carrossage trop négatif (−0°40′) = la roue penche vers l’intérieur → côté intérieur.' },
      { l: L, img: D + 'usure-rugueuse-ext.svg', q: 'Pneumatique avant droit : usure rugueuse à l’extérieur de la bande de roulement. Cause probable ?', c: ['Problème de parallélisme : trop de pincement.', 'Problème de parallélisme : trop d’ouverture.', 'Problème de carrossage trop positif.'], e: 'Rugueuse = parallélisme. Côté extérieur = la roue est tournée vers l’intérieur : trop de pincement.' },
      { l: L, img: D + 'usure-lisse-ext.svg', q: 'Usure lisse à l’extérieur de la bande de roulement. Cause probable ?', c: ['Carrossage trop positif.', 'Carrossage trop négatif.', 'Trop de pincement.'], e: 'Lisse = carrossage. Côté extérieur = la roue penche vers l’extérieur : carrossage trop positif.' },
      { l: L, img: D + 'usure-facettes.svg', q: 'Lors d’une visite, on vous signale une usure en facettes sur les pneus avant. Qu’allez-vous faire changer ?', c: ['Les pneumatiques avant et les amortisseurs avant.', 'Les ressorts avant et les amortisseurs avant.', 'Les pneumatiques avant et les rotules de direction.'], e: 'Usure en facettes = amortisseurs HS : on change les amortisseurs (par paire) et les pneus abîmés du même essieu.' },
      { l: L, img: B + 'l-d030_0.jpg', q: 'Réglage complet d’un train avant : quel réglage se fait toujours en dernier ?', c: ['Le parallélisme.', 'Le carrossage.', 'La chasse.'], e: 'Ordre : hauteur de caisse → chasse → pivot → carrossage → hauteur de crémaillère → parallélisme (toujours en dernier).' },
      { l: L, img: D + 'pneu-dot4217.svg', q: 'Que signifie le marquage DOT 4217 ?', c: ['Fabriqué la 42ᵉ semaine de 2017.', 'Fabriqué en avril 2017.', 'Fabriqué le 4 février 2017.'], e: '2 premiers chiffres = semaine, 2 derniers = année.' },
      { l: L, img: D + 'pneu-vv.svg', q: 'Que signifie le marquage « VV » sur un pneumatique militaire ?', c: ['Rechapé 2 fois.', 'Vérifié deux fois.', 'Pneumatique pour véhicule de l’avant.'], e: 'VV = pneumatique rechapé 2 fois (R = rechapé, V = recreusé).' },
      { l: L, img: D + 'pneu-r18.svg', q: 'Que signifie le marquage militaire « R18 » ?', c: ['Rechapé en 2018.', 'Radial 18 pouces.', 'Recreusé en 2018.'], e: 'R = rechapé, suivi de l’année. V = recreusé ; AR = « armée ».' },
      { l: L, img: D + 'pneu-dot4217.svg', q: 'Quelle est la durée de vie d’un pneumatique ?', c: ['20 ans.', '5 ans.', '10 ans.'], e: 'Un pneumatique est utilisable 20 ans ; sa date de fabrication se lit dans le marquage DOT (ex. DOT 4217 = 42ᵉ semaine de 2017).' },
      { l: L, img: D + 'pneu-295.svg', q: 'Sur le marquage « 295/80 R22.5 152/148 L », que signifient 152 et 148 ?', c: ['L’indice de charge en roue solo puis en roue jumelée.', 'La charge avant puis arrière en kg.', 'La vitesse maxi puis la vitesse conseillée.'], e: '152 = indice de charge en montage roue solo ; 148 = en montage roue jumelée. L = indice de vitesse.' },
      { l: L, img: D + 'pneu-185.svg', q: 'Dans le marquage « 185 70 R 15 86 T », que représente 86 ?', c: ['L’indice de charge.', 'L’indice de vitesse.', 'Le diamètre de la jante.'], e: '86 = indice de charge (charge maxi en kg dans le tableau) ; T = indice de vitesse ; 15 = diamètre en pouces.' },
      { l: L, img: B + 'l-d048_0.jpg', q: 'La pédale de frein s’enfonce lentement, le bocal est au niveau et il n’y a aucune trace de fuite. Élément incriminé ?', c: ['Le maître-cylindre tandem (fuite interne).', 'Les étriers de frein.', 'L’assistance de freinage.'], e: 'Fuite interne sans trace extérieure = maître-cylindre tandem.' },
      { l: L, img: B + 'l-d057_1.jpg', q: 'Le véhicule freine mal et la pédale est dure. Que contrôlez-vous en premier ?', c: ['L’assistance : pompe à vide, tuyau et Mastervac.', 'Le maître-cylindre tandem.', 'Le correcteur de freinage.'], e: 'Pédale dure = défaut d’assistance (aspiration, clapet, pompe à vide, servo).' },
      { l: L, img: B + 'l-d055_1.jpg', q: 'Les roues arrière bloquent au freinage, aucun témoin allumé. Élément à contrôler ?', c: ['Le correcteur (limiteur) de freinage.', 'Le maître-cylindre.', 'L’assistance de freinage.'], e: 'Le correcteur dose la pression arrière selon la charge : HS ou déréglé, l’arrière bloque.' },
      { l: L, img: B + 'l-d070_0.jpg', q: 'Contrôle du liquide de frein : point d’ébullition mesuré à 160 °C. Que faites-vous ?', c: ['Je remplace le liquide.', 'Rien, il est encore correct.', 'Je le remplace seulement s’il a plus de 2 ans.'], e: 'Au-dessus de 185 °C : performant ; 165 à 185 °C : correct (remplacer s’il a plus de 2 ans) ; en dessous de 165 °C : à remplacer.' },
      { l: L, img: B + 'l-d073_0.jpg', q: 'Freinage appuyé sur route glissante, véhicule équipé de l’ABS : la pédale pulse sous le pied. C’est :', c: ['Normal : l’ABS régule la pression.', 'Un disque voilé.', 'Une fuite interne du maître-cylindre.'], e: 'En régulation, la pompe de l’ABS refoule le liquide : pulsations de la pédale, c’est normal.' },
      { l: L, img: B + 'l-d074_0.jpg', q: 'Quel capteur de roue ABS mesure la vitesse jusqu’à 0 km/h ?', c: ['Le capteur à effet Hall.', 'Le capteur inductif.', 'Le capteur piézo-électrique.'], e: 'Le capteur inductif perd son signal à très basse vitesse ; le capteur à effet Hall (alimenté, signal carré) mesure jusqu’à 0 km/h.' },
      { l: L, img: B + 'l-d060_0.jpg', q: 'Rôle de la soupape de pression résiduelle (freins à tambours) ?', c: ['Conserver 0,5 à 1,5 bar dans le circuit arrière pour plaquer les joints des cylindres de roue.', 'Limiter la pression arrière selon la charge.', 'Signaler une fuite au conducteur.'], e: 'La SPR garde une petite pression au repos : les coupelles restent plaquées, pas de fuite ni d’entrée d’air.' },
      { l: L, img: B + 'l-d054_0.jpg', q: 'Rôle de l’ICP by-pass ?', c: ['Signaler une fuite AV ou AR et, si l’avant fuit, envoyer la pression maxi à l’arrière.', 'Limiter la pression arrière selon la charge.', 'Maintenir une pression résiduelle dans le circuit.'], e: 'Indicateur de chute de pression : témoin au tableau de bord ; fuite à l’avant → il shunte le correcteur pour freiner plus fort à l’arrière.' },
      { l: L, img: D + 'train-ps600-p-fixe.svg', q: 'Porte-satellites menant à 600 tr/min, planétaire fixe, Zc = 80, Zp = 40. Vitesse et rapport de la couronne ?', c: ['900 tr/min, marche avant multipliée.', '400 tr/min, marche avant démultipliée.', '900 tr/min, marche arrière.'], e: 'Zp·Np + Zc·Nc = (Zp + Zc)·Nps → 40 × 0 + 80 × Nc = 120 × 600 → Nc = 900 tr/min, même sens : multiplié (porte-satellites MENANT = multiplié).' },
      { l: L, img: D + 'train-lies.svg', q: 'Deux éléments d’un train épicycloïdal sont liés ensemble. Quel rapport obtenez-vous ?', c: ['Prise directe.', 'Marche arrière démultipliée.', 'Marche avant multipliée.'], e: 'Deux éléments liés = tout le train tourne d’un bloc : prise directe (rapport 1).' },
      { l: L, img: D + 'train-p1200-ps-fixe.svg', q: 'Planétaire menant à 1 200 tr/min (Zp = 30), porte-satellites bloqué, couronne Zc = 40. Que fait la couronne ?', c: ['Elle tourne à 900 tr/min en marche arrière.', 'Elle tourne à 800 tr/min en marche arrière.', 'Elle tourne à 900 tr/min en marche avant.'], e: 'Nps = 0 → 30 × 1 200 + 40 × Nc = 0 → Nc = −900 tr/min : porte-satellites FIXE = marche arrière.' },
      { l: L, img: B + 'l-d009_0.jpg', q: 'Le véhicule plonge de l’avant au freinage : comment s’appelle ce mouvement de caisse ?', c: ['Le tangage.', 'Le roulis.', 'Le lacet.'], e: 'Tangage = avant / arrière ; roulis = gauche / droite ; lacet = autour de l’axe vertical ; pompage = vertical.' }
    ]
  });

  /* ======================= PNEUMATIQUE ======================= */
  var P = D + 'schema-pneu-theorique.jpg';
  REV.addExercises('pneu', {
    lessons: [lesson(L, 'UV2 — Questions types : freinage pneumatique', ['Rouge = main automatique (alimentation) ; jaune = main directe (commande).', 'Test rupture : manomètre sur l’automatique, fuite sur la directe.', 'Tristop : l’air défreine, le ressort freine.', 'Remplissage 6 à 11 min ; temps de réponse 0,6 s.'], 'ROUGE = AUTOMATIQUE · JAUNE = DIRECTE', ['1 entrée · 2 sortie · 3 échappement · 4 pilotage', '43 = pilotage par absence d’air (parc)', 'VNAE : pas d’addition service + ressort'], 'Le ressort freine, l’air défreine.')],
    questions: [
      { l: L, img: P, q: 'Sur le schéma, à quoi sert l’élément 17 (valve de barrage à retour partiel) ?', c: ['N’alimenter un circuit qu’une fois la pression amont atteinte (priorité de remplissage).', 'Garder la pression en aval en cas de fuite en amont.', 'Assécher l’air comprimé.'], e: 'Valve de barrage = priorité de remplissage ; le retour partiel laisse revenir une partie de l’air.' },
      { l: L, img: P, q: 'Sur le schéma, donnez le nom de l’élément 7.', c: ['Clapet anti-retour.', 'Valve de barrage à retour total.', 'Valve de purge d’eau.'], e: 'Élément 7 = clapet anti-retour : il garde la pression du circuit de parc si une fuite apparaît en amont.' },
      { l: L, img: P, q: 'Sur le schéma, la tête d’accouplement ROUGE (élément 12) correspond à :', c: ['La main automatique : alimentation permanente de la remorque.', 'La main directe : commande du freinage de la remorque.', 'La main de secours du frein de parc.'], e: 'Rouge = automatique = pression constante (alimentation). Jaune = directe = pression délivrée (commande).' },
      { l: L, img: P, q: 'Sur le schéma, la tête d’accouplement JAUNE correspond à :', c: ['La main directe : pression délivrée pour commander le freinage de la remorque.', 'La main automatique : alimentation des réservoirs de la remorque.', 'Le retour à l’atmosphère.'], e: 'Jaune = directe = commande ; rouge = automatique = alimentation.' },
      { l: L, img: P, q: 'Vous constatez de l’air en permanence à la main directe arrière. Quelle cause est possible ?', c: ['Le frein de parc est serré (pilotage 43 vidé).', 'Le correcteur de freinage est mal réglé.', 'Le compresseur est hors service.'], e: 'Causes possibles : frein de parc serré, frein d’alignement enclenché, défaut du pilotage 43, VCR grippée. Jamais le correcteur (il n’agit que sur le porteur).' },
      { l: L, img: P, q: 'Moteur au ralenti, le temps de remplissage jusqu’à la pression de régulation est de 14 minutes. Conclusion ?', c: ['Hors norme (6 à 11 min) : contrôler le compresseur, les fuites et le régulateur.', 'Normal, la norme tolère jusqu’à 15 minutes.', 'Normal pour un véhicule avec remorque.'], e: 'Norme européenne : toutes les bouteilles remplies entre 6 et 11 minutes au ralenti.' },
      { l: L, img: P, q: 'Temps de réponse maximal imposé par la norme européenne au freinage pneumatique ?', c: ['0,6 seconde.', '6 secondes.', '11 minutes.'], e: 'Temps de réponse ≤ 0,6 s ; ne pas confondre avec le temps de remplissage (6 à 11 min).' },
      { l: L, img: B + 'l-p045_0.jpg', q: 'Pour contrôler la fonction rupture de la VCR, où branchez-vous le manomètre ?', c: ['Sur la main automatique (rouge), puis je crée une fuite sur la main directe.', 'Sur la main directe (jaune), puis je crée une fuite sur la main automatique.', 'Sur le réservoir du circuit avant.'], e: 'Véhicule à pression de régulation, le conducteur freine, fuite sur la directe → la pression de l’automatique doit tomber à 0 bar.' },
      { l: L, img: B + 'l-p045_0.jpg', q: 'Quelles conditions déclenchent la fonction rupture de la VCR ?', c: ['Le conducteur freine ET il y a une fuite sur le circuit direct.', 'Le frein de parc est serré.', 'La pression dépasse la pression de régulation.'], e: 'Les deux conditions ensemble : un piston coupe 95 % de l’alimentation, la pression de l’automatique chute et la VRU freine la remorque.' },
      { l: L, img: Y + 'agb03r-p71-22.png', q: 'Sur la VCR à triple pilotage, quel est le rôle du pilotage 43 ?', c: ['Il reçoit l’information du frein de parc (pilotage par absence d’air) pour piloter la VCR.', 'Il reçoit l’information du frein de service avant pour piloter la VCR.', 'Il reçoit l’information du frein de service arrière pour piloter la VCR.'], e: 'Le pilotage 43 ne commande pas le frein de parc : il reçoit l’information du circuit de frein de parc et pilote la VCR par absence d’air (pilotage négatif). 41 et 42 reçoivent les informations des circuits de frein de service (avant, arrière).', r: 'Les pilotages 41, 42, 43 REÇOIVENT une information et pilotent la VCR.' },
      { l: L, img: Y + 'agb03r-p71-26.png', q: 'Rôle de la valve relais d’urgence (VRU) de la remorque ?', c: ['Commander le freinage selon la main directe et freiner automatiquement si la main automatique casse.', 'Assécher l’air de la remorque.', 'Limiter la pression dans les vases de la remorque.'], e: 'La VRU freine la remorque proportionnellement à la main jaune, et en urgence si la conduite rouge est rompue.' },
      { l: L, img: B + 'l-p066_2.jpg', q: 'Comment contrôler la VRU d’une remorque attelée, à la pression de régulation ?', c: ['Débrancher la main automatique : la remorque doit freiner seule.', 'Débrancher la main directe : la remorque doit freiner seule.', 'Serrer le frein de parc du tracteur.'], e: 'Sans alimentation (main rouge), la VRU déclenche le freinage d’urgence de la remorque.' },
      { l: L, img: Y + 'agb03r-p72-07.png', q: 'Sur un cylindre Tristop, que se passe-t-il si l’air de la chambre à ressort disparaît ?', c: ['Le ressort serre le frein.', 'Le frein se desserre.', 'Rien, seul le frein de service agit.'], e: 'Tristop : l’air comprime le ressort pour DÉFREINER ; plus d’air = le ressort freine (sécurité).' },
      { l: L, img: Y + 'agb03r-p71-23.png', q: 'Rôle de la valve de non-addition des efforts (VNAE) ?', c: ['Éviter d’additionner l’effort du frein de service et celui du ressort sur un Tristop.', 'Donner la priorité au circuit de parc.', 'Freiner la remorque en cas de rupture.'], e: 'Frein de parc serré + appui sur la pédale : la VNAE réalimente la chambre à ressort pour ne pas cumuler les deux efforts.' },
      { l: L, img: B + 'l-p021_0.jpg', q: 'Rôle du dessiccateur ?', c: ['Assécher l’air : plus de condensation, plus besoin d’antigel.', 'Répartir l’air entre les circuits.', 'Limiter la pression de régulation.'], e: 'Dessiccation – régénération : air sec, circuits protégés, purges et antigel inutiles.' },
      { l: L, img: Y + 'agb03r-p72-05.png', q: 'Rôle de la valve de protection 4 circuits ?', c: ['Alimenter les circuits dans un ordre précis et isoler un circuit défaillant.', 'Assécher l’air.', 'Commander le frein de parc.'], e: 'Si un circuit fuit, les autres restent alimentés à la pression de tarage du clapet du circuit défaillant.' },
      { l: L, img: Y + 'agb03r-p71-02.png', q: 'Une fuite apparaît sur la conduite en amont d’un réservoir équipé d’un clapet anti-retour :', c: ['La pression du réservoir est conservée.', 'Le réservoir se vide par la fuite.', 'Le compresseur s’arrête.'], e: 'Le clapet anti-retour ne laisse passer l’air que dans un sens : il garde la pression en aval.' },
      { l: L, img: Y + 'agb03r-p71-15.png', q: 'Sur ce symbole, l’orifice repéré 3 est :', c: ['L’échappement (mise à l’atmosphère).', 'L’alimentation.', 'Le pilotage.'], e: '1 = alimentation · 2 = utilisation · 3 = échappement · 4 = pilotage (commande).' },
      { l: L, img: Y + 'agb03r-p71-12.png', q: 'Sur ce symbole, l’orifice repéré 4 est :', c: ['Le pilotage (commande).', 'L’échappement.', 'L’utilisation.'], e: '4 = commande ; 41, 42, 43… s’il y a plusieurs pilotages (43 = pilotage par absence d’air).' },
      { l: L, img: Y + 'agb03r-p72-00.png', q: 'Rôle du correcteur de freinage ?', c: ['Adapter l’effort de freinage de l’essieu arrière à la charge du véhicule.', 'Donner la priorité de remplissage.', 'Commander le freinage de la remorque.'], e: 'Correcteur à commande mécanique (lié à l’essieu) ou pneumatique (suspension pneumatique) ; il peut intégrer la valve relais.' },
      { l: L, img: Y + 'agb03r-p71-04.png', q: 'Rôle du robinet de frein de remorque (d’alignement) ?', c: ['Freiner la remorque seule, proportionnellement au levier.', 'Freiner le tracteur seul.', 'Couper l’alimentation de la remorque.'], e: 'Il commande le freinage de la remorque indépendamment du tracteur (alignement de l’ensemble).' },
      { l: L, img: B + 'l-p048_1.jpg', q: 'Frein de stationnement : sur quelle pente un véhicule seul, en charge, doit-il tenir ?', c: ['18 %.', '12 %.', '30 %.'], e: 'Véhicule seul en charge : 18 % ; ensemble routier en charge : 12 % (seul le tracteur freiné).' }
    ]
  });

  /* ======================= HYDRAULIQUE ======================= */
  var PE = 'pelle-emad1.jpg', TH = 'transmission-hydrostatique.jpg';
  REV.addExercises('hydro', {
    lessons: [lesson(L, 'UV2 — Questions types : hydraulique', ['Vitesse = débit ; force = pression ; moteur qui cale = puissance.', 'Tous les récepteurs → appareil commun ; un seul → appareil de sa section.', '2 sens → en amont du distributeur (balance) ; 1 sens → sur une ligne (limiteur secondaire).', 'Circuit fermé : BP au neutre = gavage ; en marche = balayage (plus bas).'], 'VITESSE = DÉBIT · FORCE = PRESSION', ['Q = V × N / 1000', 'v = Q / (6 × S)', 'Pu = P × Q / 600', 'P = F / S'], 'Combien de récepteurs ? Combien de sens ? Vitesse ou force ?')],
    questions: [
      { l: L, img: PE, q: 'Tous les mouvements de la pelle manquent de force, dans les deux sens. Analysez le problème et donnez votre diagnostic ?', c: ['Problème de force, donc de pression sur tous les récepteurs dans les 2 sens : j’incrimine un appareil commun (annulation de débit ou limiteur principal).', 'Problème de vitesse, donc de débit sur 1 récepteur : j’incrimine la balance individuelle de pression.', 'Problème de force sur 1 récepteur dans 1 sens : j’incrimine le limiteur de pression secondaire.'], e: 'Tous les récepteurs → appareil commun ; manque de force → pression.' },
      { l: L, img: PE, q: 'La flèche manque de force uniquement en montée ; tous les autres mouvements sont normaux. Analysez le problème et donnez votre diagnostic ?', c: ['Problème de force, donc de pression sur 1 récepteur dans 1 sens : j’incrimine le limiteur de pression secondaire de la ligne de montée.', 'Problème de vitesse, donc de débit sur 1 récepteur dans 2 sens : j’incrimine la balance individuelle.', 'Problème de force sur tous les récepteurs : j’incrimine l’annulation de débit.'], e: '1 récepteur, 1 sens → appareil placé sur la ligne : limiteur secondaire.' },
      { l: L, img: PE, q: 'Un seul vérin est lent dans les deux sens, sa force est normale. Analysez le problème et donnez votre diagnostic ?', c: ['Problème de vitesse, donc de débit sur 1 récepteur dans 2 sens : j’incrimine sa balance individuelle de pression.', 'Problème de force sur 1 récepteur dans 1 sens : j’incrimine le limiteur secondaire.', 'Problème de vitesse sur tous les récepteurs : j’incrimine la pompe.'], e: '1 récepteur, 2 sens → appareil en amont de son distributeur : la balance individuelle (BIP + distributeur = régulateur de débit 2 voies).' },
      { l: L, img: PE, q: 'Sur cette pelle, récepteurs en butée et fonctionnement normal, quelle pression lisez-vous sur la ligne de service ?', c: ['240 bar (annulation de débit).', '280 bar (limiteur de secours).', '27 bar (tiroir LS).'], e: 'En butée, l’annulation de débit (240 b) ramène la pompe à débit nul. Si on lit 280 b, c’est le limiteur de secours qui travaille : annulation de débit en défaut.' },
      { l: L, img: PE, q: 'Rôle du tiroir d’annulation de débit ?', c: ['Définir la pression maxi du circuit et, quand un récepteur arrive en butée, réduire le débit de la pompe pour neutraliser la puissance de coin.', 'Protéger les vérins contre les chocs.', 'Donner la priorité à la direction.'], e: 'Sans annulation, la pompe débiterait à pression maxi en butée : puissance perdue, moteur qui cale.' },
      { l: L, img: PE, q: 'Rôle de la balance individuelle de pression placée avant chaque distributeur ?', c: ['Garder un ΔP constant aux bornes du distributeur : la vitesse du récepteur reste la même en utilisation simultanée.', 'Limiter la pression maxi du circuit.', 'Isoler le circuit de commande.'], e: 'Balance individuelle + distributeur = régulateur de débit 2 voies : le récepteur le moins chargé ne s’emballe pas.' },
      { l: L, img: PE, q: 'Le moteur thermique cale dès qu’un récepteur arrive en butée. Diagnostic ?', c: ['Annulation de débit grippée ou sur-tarée : la puissance de coin n’est plus neutralisée.', 'Limiteur secondaire détaré.', 'Balance individuelle bloquée ouverte.'], e: 'Moteur qui cale = problème de puissance (P × Q trop grand) sur tous les récepteurs → annulation de débit.' },
      { l: L, img: TH, q: 'Moteur tournant, au neutre : quelle pression lisez-vous dans les deux branches de la boucle ?', c: ['30 bar (limiteur de gavage).', '27 bar (limiteur de balayage).', '0 bar.'], e: 'Au neutre le tiroir de balayage est fermé : le limiteur de gavage fixe la pression des deux branches.' },
      { l: L, img: TH, q: 'Rôle des soupapes haute pression (5) tarées à 360 bar ?', c: ['Protéger la boucle et le moteur hydraulique contre les chocs.', 'Définir la pression de service maximale.', 'Définir la pression de la branche basse pression.'], e: 'La pression de service maxi est donnée par l’annulation de débit (320 b) ; les soupapes HP, tarées au-dessus, écrêtent les pointes.' },
      { l: L, img: TH, q: 'Engin en marche, roues bloquées contre un obstacle : quel appareil limite la pression de la branche HP ?', c: ['La soupape d’annulation de débit (320 bar).', 'Les soupapes haute pression (360 bar).', 'Le limiteur de gavage (30 bar).'], e: 'Roues bloquées : c’est l’annulation de débit qui travaille (elle ramène la pompe à débit nul), pas les soupapes HP.' },
      { l: L, img: TH, q: 'Pourquoi le limiteur de balayage (27 b) est-il taré plus bas que le limiteur de gavage (30 b) ?', c: ['Pour que l’huile chaude de la boucle parte au refroidisseur et soit remplacée par le gavage.', 'Pour protéger la pompe de gavage.', 'Pour augmenter la vitesse de l’engin.'], e: 'Sinon l’huile de la boucle ne serait jamais renouvelée ni refroidie.' },
      { l: L, img: TH, q: 'Rôle de la pompe de gavage (2) ?', c: ['Compenser les fuites, plaquer les pistons, lubrifier et alimenter la servocommande.', 'Entraîner le moteur hydraulique.', 'Refroidir le moteur thermique.'], e: 'Elle réalimente la branche basse pression et régénère l’huile de la boucle.' },
      { l: L, img: TH, q: 'Rôle du robinet (12) sur la boucle de puissance ?', c: ['Permettre le remorquage de l’engin (mise à flot du moteur hydraulique).', 'Isoler la bâche pour la vidange.', 'Régler la pression de gavage.'], e: 'Robinet ouvert : les deux branches communiquent, le moteur hydraulique tourne librement pour remorquer.' },
      { l: L, img: TH, q: 'Moteur hydraulique à régulation de puissance : que se passe-t-il quand la charge augmente ?', c: ['Sa cylindrée augmente : le couple augmente et la vitesse diminue.', 'Sa cylindrée diminue : la vitesse augmente.', 'La pression de gavage augmente.'], e: 'Il adapte sa cylindrée à la charge pour garder une puissance constante.' },
      { l: L, img: Y + 'agd20-p020-0.png', q: 'Avantage du régulateur de débit 3 voies par rapport au 2 voies ?', c: ['L’excédent retourne à la bâche à une pression juste suffisante : moins de pertes.', 'Il est plus précis sur la vitesse.', 'Il protège le circuit contre les chocs.'], e: 'Le 2 voies fait partir l’excédent par le limiteur, à pression maxi : pertes et échauffement.' },
      { l: L, img: Y + 'agd19-p109-0.png', q: 'Avantage du réducteur de pression 3 voies par rapport au 2 voies ?', c: ['Son retour bâche protège le circuit aval d’une surpression.', 'Il consomme plus de débit.', 'Il est fermé au repos.'], e: 'Le 2 voies ne protège pas l’aval si la pression y monte ; le 3 voies évacue vers la bâche.' },
      { l: L, img: Y + 'agd19-p108-1.png', q: 'Au repos, un réducteur de pression est :', c: ['Ouvert, piloté par la pression aval.', 'Fermé, piloté par la pression amont.', 'Fermé, piloté par la pression aval.'], e: 'Réducteur : ouvert au repos, pilotage AVAL. Limiteur : fermé au repos, pilotage AMONT.' },
      { l: L, img: Y + 'agd19-p100-2.png', q: 'Au repos, un limiteur de pression est :', c: ['Fermé, piloté par la pression amont.', 'Ouvert, piloté par la pression aval.', 'Ouvert, piloté par la pression amont.'], e: 'Il s’ouvre vers la bâche quand la pression amont atteint le tarage de son ressort.' },
      { l: L, img: Y + 'agd19-p110-2.png', q: 'Rôle de la soupape de séquence ?', c: ['Donner la priorité d’alimentation à une partie du circuit (ordre de fonctionnement).', 'Maîtriser la descente d’une charge.', 'Limiter la pression maxi du circuit.'], e: 'Fermée au repos, elle n’alimente la suite du circuit qu’une fois sa pression de tarage atteinte.' },
      { l: L, img: Y + 'agd20-p032-0.png', q: 'Rôle du clapet anti-retour piloté ?', c: ['Empêcher le déplacement d’un récepteur en l’absence de génération.', 'Choisir la plus forte pression de deux branches.', 'Réguler le débit.'], e: 'Il bloque le retour tant qu’il n’est pas piloté : le vérin reste en position (bloc de sécurité = 2 clapets pilotés).' },
      { l: L, img: Y + 'gd08-p17-367.png', q: 'Une pompe de 25 cm³/tr est entraînée à 2 400 tr/min. Quel est son débit ?', c: ['60 L/min.', '96 L/min.', '6 L/min.'], e: 'Q = V × N / 1000 = 25 × 2 400 / 1 000 = 60 L/min.' },
      { l: L, img: Y + 'agd19-p081-2.png', q: 'Un vérin de 40 cm² est alimenté à 60 L/min. Vitesse de sortie de tige ?', c: ['0,25 m/s.', '1,5 m/s.', '0,4 m/s.'], e: 'v = Q / (6 × S) = 60 / (6 × 40) = 0,25 m/s.' },
      { l: L, img: Y + 'agd19-p010-0.png', q: 'Circuit à 200 bar avec un débit de 60 L/min. Puissance hydraulique ?', c: ['20 kW.', '12 kW.', '120 kW.'], e: 'Pu = P × Q / 600 = 200 × 60 / 600 = 20 kW.' },
      { l: L, img: Y + 'agd19-p081-2.png', q: 'Un vérin de 50 cm² doit pousser 10 000 daN. Pression nécessaire ?', c: ['200 bar.', '500 bar.', '20 bar.'], e: 'P = F / S = 10 000 / 50 = 200 bar.' }
    ]
  });

  /* ======================= MOTORISATION ======================= */
  REV.addExercises('moteur', {
    lessons: [lesson(L, 'UV2 — Questions types : motorisation', ['Bosch 1ʳᵉ gén. : régulateur HP. Delphi : régulateur de débit (IMV), pas de régulateur HP.', 'Débit injecté = temps d’ouverture + pression de rampe + trous.', 'Capteur HP contact mis : 0,5 V ; au démarreur 1 à 1,5 V = HP bonne.', 'FAP ≈ 550 °C · EGR = NOx · cétane ≥ 51.'], 'BOSCH = RÉGULATEUR HP · DELPHI = IMV', ['Delphi : chute HP par les retours injecteurs', 'Accéléromètre = recale la pré-injection', 'Pompe HP changée en dernier'], 'Delphi : pas de régulateur haute pression.')],
    questions: [
      { l: L, img: G + 'g143_0.jpg', q: 'Pour faire chuter la haute pression sur un système Bosch 1ʳᵉ génération, le calculateur :', c: ['Ouvre le régulateur de haute pression.', 'Agit sur les retours des injecteurs.', 'Coupe la pompe basse pression.'], e: 'Bosch 1ʳᵉ gén. : la pompe débite toujours au maxi, le régulateur HP crée une fuite contrôlée.' },
      { l: L, img: G + 'g143_0.jpg', q: 'Pour faire monter la haute pression sur un système Bosch 2ᵉ génération, le calculateur agit sur :', c: ['Le régulateur de débit à l’entrée de la pompe HP.', 'La vitesse de rotation du moteur.', 'La pompe basse pression.'], e: '2ᵉ génération : régulateur de débit en entrée de pompe (moins d’échauffement) ; 3ᵉ génération : régulateur de débit + régulateur HP.' },
      { l: L, img: G + 'g157_0.jpg', q: 'Le système common rail Delphi possède-t-il un régulateur haute pression ?', c: ['Non : la haute pression est réglée par le régulateur de débit (IMV).', 'Oui, sur la rampe.', 'Oui, sur la pompe HP.'], e: 'Delphi : pas de régulateur HP ; on monte la pression avec l’IMV et on la fait chuter par les retours des injecteurs.' },
      { l: L, img: G + 'g167_1.jpg', q: 'Sur le régulateur de débit IMV Delphi, si le courant de commande augmente :', c: ['Moins de gazole est envoyé aux pistons : la pression baisse.', 'Plus de gazole est envoyé aux pistons : la pression monte.', 'L’IMV reste ouvert quel que soit le courant.'], e: 'L’IMV est normalement ouvert : plus de courant = moins de débit.' },
      { l: L, img: G + 'g154_0.jpg', q: 'Sur un common rail, le débit injecté dépend :', c: ['Du temps d’ouverture de l’injecteur, de la pression de rampe et des sections des trous.', 'Uniquement du régime moteur.', 'Uniquement de la pompe basse pression.'], e: 'Débit = temps d’ouverture + pression de rampe + somme des sections des trous.' },
      { l: L, img: G + 'g155_0.jpg', q: 'Rôle de la pré-injection ?', c: ['Faire monter la température de la chambre : délai d’auto-inflammation, bruit et HC réduits.', 'Refroidir la chambre de combustion.', 'Régénérer le filtre à particules.'], e: 'Petite injection avant la principale ; supprimée au-delà de 2 000 tr/min.' },
      { l: L, img: G + 'g155_0.jpg', q: 'Au-delà de quel régime la pré-injection est-elle supprimée ?', c: ['2 000 tr/min.', '800 tr/min.', '4 500 tr/min.'], e: 'Au-delà de 2 000 tr/min, il n’y a plus de pré-injection.' },
      { l: L, img: G + 'g149_0.jpg', q: 'Pompe HP Bosch : que fait le clapet de sécurité quand la pression d’alimentation est inférieure à 0,8 bar ?', c: ['Il ne laisse passer le gazole que pour graisser et refroidir la pompe.', 'Il alimente les éléments de pompage.', 'Il arrête le moteur.'], e: '< 0,8 bar : graissage / refroidissement ; > 0,8 bar : alimentation des éléments de pompage.' },
      { l: L, img: G + 'g149_1.jpg', q: 'Rôle du désactivateur du 3ᵉ piston de la pompe HP Bosch ?', c: ['Réduire la puissance absorbée et l’échauffement du gazole en faible charge.', 'Augmenter la pression au démarrage.', 'Couper l’injection en décélération.'], e: 'En faible charge, un piston est mis hors service.' },
      { l: L, img: G + 'g162_0.jpg', q: 'Après le remplacement d’un injecteur Delphi, que faut-il faire ?', c: ['Entrer son code C2I dans le calculateur.', 'Rien, l’injecteur s’adapte seul.', 'Remplacer tous les injecteurs.'], e: 'Chaque injecteur Delphi porte un code C2I (étiquette) à programmer dans le calculateur.' },
      { l: L, img: G + 'g151_0.jpg', q: 'Résistance normale d’un injecteur électromagnétique de common rail ?', c: ['Environ 0,5 Ω.', 'Environ 200 kΩ.', 'Environ 60 Ω.'], e: 'Électromagnétique ≈ 0,5 Ω ; piézo-électrique ≈ 200 kΩ (et ≈ 4 µF).' },
      { l: L, img: G + 'g157_0.jpg', q: 'Rôle de l’accéléromètre sur le système Delphi ?', c: ['Recaler le débit de pré-injection de chaque injecteur (détecte le cylindre trop bruyant).', 'Mesurer le régime moteur.', 'Mesurer la pression de rampe.'], e: 'Capteur piézo placé entre les cylindres ; il détecte aussi un injecteur bloqué ouvert.' },
      { l: L, img: G + 'g136_0.jpg', q: 'Couronne du vilebrequin Bosch à 60 dents moins 2 : à quoi servent les 2 dents manquantes ?', c: ['À repérer le PMH des cylindres 1 et 4.', 'À mesurer la pression de rampe.', 'À repérer le cylindre en compression.'], e: 'Le capteur PMH (inductif) donne le régime et le PMH 1-4 ; le capteur de phase (arbre à cames) donne le cylindre en compression.' },
      { l: L, img: G + 'g136_1.jpg', q: 'Le capteur de phase (arbre à cames) est hors service. Conséquence ?', c: ['Le moteur ne démarre pas.', 'Aucune conséquence.', 'Le moteur passe en surrégime.'], e: 'Sans l’information du 1ᵉʳ cylindre en compression, le calculateur ne sait pas quel injecteur commander.' },
      { l: L, img: G + 'g137_1.jpg', q: 'Moteur qui ne démarre pas (Delphi). Tension du capteur haute pression contact mis ?', c: ['0,5 V : capteur et ligne bons.', '5 V : capteur bon.', '1,5 V : capteur bon.'], e: 'Contact mis : 0,5 V = bon ; plus de 1 V = capteur HS ou ligne en court-circuit.' },
      { l: L, img: G + 'g157_0.jpg', q: 'Delphi, moteur qui ne démarre pas : au démarreur, le capteur HP donne 1 à 1,5 V. Conclusion ?', c: ['Circuits BP et HP bons : contrôler les capteurs PMH et d’arbre à cames.', 'Remplacer la pompe HP.', 'IMV grippé fermé.'], e: '1 à 1,5 V au démarreur = pression correcte ; plus de 1,5 V = IMV ; 0,5 à 0,9 V = fuites, IMV, clapet, puis pompe.' },
      { l: L, img: G + 'g157_0.jpg', q: 'Delphi : au démarreur, le capteur HP donne largement plus de 1,5 V et le moteur ne démarre pas. Élément à contrôler ?', c: ['Le régulateur de débit (IMV) : résistance, tension, grippage.', 'Les capteurs PMH et d’arbre à cames.', 'La pompe haute pression en premier.'], e: 'Pression trop haute au démarreur → dysfonctionnement du régulateur de débit.' },
      { l: L, img: G + 'g143_0.jpg', q: 'Bosch CP1 : au démarreur, le capteur HP donne moins de 1 V. Que contrôlez-vous d’abord ?', c: ['La pompe d’alimentation et le filtre (ΔP maxi 0,3 bar).', 'Les capteurs PMH et de phase.', 'Le code des injecteurs.'], e: 'Pression insuffisante : alimentation et filtre, puis clapet, fuites, régulateur HP (≈ 2 Ω), et la pompe HP en dernier.' },
      { l: L, img: G + 'g143_0.jpg', q: 'Rôle du limiteur de débit placé sur la rampe commune ?', c: ['Couper le débit si un injecteur reste ouvert ou si une canalisation casse.', 'Régler la pression de rampe.', 'Limiter le régime maxi.'], e: 'Il protège le moteur d’un noyage en cas de grippage ouvert d’un injecteur.' },
      { l: L, img: G + 'g140_1.jpg', q: 'Rôle de l’EGR (recyclage des gaz d’échappement) ?', c: ['Diminuer les NOx en abaissant la température de combustion.', 'Filtrer les particules de suie.', 'Réduire le CO et les HC.'], e: 'L’EGR intervient quand la température de combustion dépasse ≈ 1 300 °C : on réinjecte une partie des gaz d’échappement à l’admission.' },
      { l: L, q: 'Comment se régénère le filtre à particules ?', c: ['En élevant la température des gaz (≈ 550 °C) pour brûler les suies.', 'En injectant de l’AdBlue.', 'En le nettoyant à l’eau à chaque vidange.'], e: 'FAP : il filtre puis brûle les suies.' },
      { l: L, q: 'Le système SCR (AdBlue) a pour rôle :', c: ['De réduire les NOx.', 'De filtrer et brûler les particules de suie.', 'De réduire le CO.'], e: 'L’AdBlue libère de l’ammoniac qui réduit les NOx ; actif au-dessus de 180 °C au catalyseur.' },
      { l: L, q: 'Du carburéacteur (indice de cétane ≈ 42) est utilisé dans un moteur diesel. Conséquence ?', c: ['Démarrage difficile, cognements et fumées ; usure de l’injection.', 'Meilleur démarrage à froid.', 'Baisse des cognements.'], e: 'Cétane < 51 = délai d’auto-inflammation allongé ; son mauvais pouvoir lubrifiant use l’injection.' },
      { l: L, q: 'Gazole par grand froid : quel phénomène apparaît en premier ?', c: ['Le point de trouble (premiers cristaux de paraffine).', 'La température limite de filtrabilité.', 'Le point d’écoulement.'], e: 'Ordre en refroidissant : point de trouble → TLF (filtre bouché) → point d’écoulement (gazole figé).' },
      { l: L, img: G + 'g124_0.jpg', q: 'Sur un turbocompresseur, la pression maxi d’admission est limitée par :', c: ['La soupape de décharge (wastegate).', 'L’intercooler.', 'Le correcteur LDA.'], e: 'La wastegate dérive les gaz d’échappement hors de la turbine.' },
      { l: L, img: G + 'g122_1.jpg', q: 'Turbo à géométrie variable, à bas régime :', c: ['Les ailettes sont fermées : les gaz sont accélérés, le couple augmente.', 'Les ailettes sont ouvertes au maximum.', 'La turbine est arrêtée.'], e: 'Bas régime : fermé (couple) ; haut régime : ouvert.' },
      { l: L, img: G + 'g125_0.jpg', q: 'Rôle de l’échangeur air-air (intercooler) ?', c: ['Refroidir l’air comprimé pour le rendre plus dense.', 'Réchauffer l’air à froid.', 'Filtrer l’air d’admission.'], e: 'Air plus froid = plus dense = meilleur remplissage (−10 °C ≈ +3 % de puissance).' }
    ]
  });

  /* ======================= ÉQUIPEMENT ÉLECTRIQUE ======================= */
  REV.addExercises('equip', {
    lessons: [lesson(L, 'UV2 — Questions types : équipement électrique', ['Moteur de démarreur < 1 Ω ; maintien ≈ 2 × appel.', 'Mini au démarrage : 9,6 V (12 V) · 19,2 V (24 V).', 'Lampe HS : 9 diodes = ne charge plus ; 6 diodes rég. incorporé = continue.', 'CAN : 2 × 120 Ω → 60 Ω ; fils torsadés contre les perturbations.'], 'APPEL · MAINTIEN · 9 / 6 DIODES · CAN', ['Régulation 12 V : 13,5 à 15 V', '24 V : 28 à 29,5 V', 'Recharge à C/10 pendant 10 h'], 'Batterie à recharger avant tout diagnostic du démarreur.')],
    questions: [
      { l: L, img: A + 'dem-schema-principe.jpg', q: 'Dans un circuit de démarrage, si l’enroulement d’appel est coupé, que se passe-t-il ?', c: ['Rien : le noyau n’est pas attiré.', 'Le solénoïde colle par intermittence.', 'Le démarreur tourne sans engrener.'], e: 'Appel coupé = rien ne se passe ; maintien coupé = claquements (effet mitraillette).' },
      { l: L, img: A + 'dem-solenoide.jpg', q: 'Entre quelles bornes contrôle-t-on l’enroulement de maintien du solénoïde ?', c: ['Entre EXC et la masse.', 'Entre EXC et +DEM.', 'Entre +BAT et +DEM.'], e: 'Appel : EXC ↔ +DEM (en série avec le moteur) ; maintien : EXC ↔ masse.' },
      { l: L, img: A + 'dem-solenoide.jpg', q: 'L’enroulement d’appel mesure 2 Ω. Quelle valeur attendez-vous pour l’enroulement de maintien ?', c: ['Environ 4 Ω.', 'Environ 1 Ω.', 'Environ 0,2 Ω.'], e: 'Maintien ≈ 2 × appel (2 Ω → 4 Ω ; 3 Ω → 6 Ω).' },
      { l: L, img: A + 'dem-coupe.jpg', q: 'Vous mesurez 7 Ω sur le moteur d’un démarreur. Conclusion ?', c: ['Le moteur est hors service (il doit faire moins de 1 Ω).', 'Valeur normale.', 'Il faut contrôler la batterie.'], e: 'Le moteur électrique du démarreur fait moins de 1 Ω.' },
      { l: L, img: A + 'dem-circuit.jpg', q: 'Réseau 12 V : tension minimale aux bornes de la batterie pendant le lancement ?', c: ['9,6 V.', '12 V.', '6 V.'], e: '80 % de la tension nominale : 9,6 V en 12 V, 19,2 V en 24 V.' },
      { l: L, img: A + 'dem-circuit.jpg', q: 'Réseau 24 V : 25,3 V aux batteries et 23,8 V au +BAT du démarreur pendant le lancement. Diagnostic ?', c: ['Perte en ligne sur le câble positif (chute de plus de 1 V).', 'Batteries déchargées.', 'Démarreur en court-circuit.'], e: '1,5 V de chute entre batterie et démarreur : résistance parasite sur la ligne + (cosses, câble).' },
      { l: L, img: A + 'dem-circuit.jpg', q: 'Réseau 24 V : 22 V aux batteries pendant le lancement, mais le démarreur peine. Élément en cause ?', c: ['Le démarreur.', 'Les batteries.', 'Le contacteur à clé.'], e: 'Les batteries tiennent (> 19,2 V) : c’est le démarreur qui est en cause.' },
      { l: L, img: A + 'dem-grognard.jpg', q: 'Contrôle de l’induit au grognard : la lame de scie vibre. Conclusion ?', c: ['L’induit est en court-circuit.', 'L’induit est bon.', 'Les balais sont usés.'], e: 'La lame ne doit pas vibrer ; si elle vibre, il y a un court-circuit entre spires.' },
      { l: L, img: A + 'dem-controle-solenoide.jpg', q: 'Solénoïde déposé, + sur EXC et − sur DEM : le relais s’enclenche. Vous avez contrôlé :', c: ['L’enroulement d’appel.', 'L’enroulement de maintien.', 'La lame de contact.'], e: '− sur DEM = appel ; − sur la carcasse = maintien ; − sur BAT = lame de contact.' },
      { l: L, img: A + 'bat-description.jpg', q: 'Deux batteries de 12 V 60 Ah sont montées en série. Résultat ?', c: ['24 V et 60 Ah.', '12 V et 120 Ah.', '24 V et 120 Ah.'], e: 'Série : les tensions s’additionnent ; parallèle : les capacités s’additionnent.' },
      { l: L, img: A + 'bat-description.jpg', q: 'Recharge classique d’une batterie de 80 Ah ?', c: ['8 A pendant 10 heures.', '80 A pendant 1 heure.', '0,8 A pendant 10 heures.'], e: 'Courant de charge = 1/10 de la capacité, pendant 10 h.' },
      { l: L, img: A + 'bat-description.jpg', q: 'Batterie 12 V de 70 Ah : quel courant appliquer pour l’essai d’aptitude au démarrage ?', c: ['210 A pendant 15 secondes, 3 fois.', '70 A pendant 1 minute.', '7 A pendant 10 heures.'], e: 'Essai : 3 × la capacité pendant ≈ 15 s, 3 fois avec 1 min de repos ; au 3ᵉ essai, plus de 9 V.' },
      { l: L, img: A + 'bat-description.jpg', q: 'Batterie 12 V rechargée : au 3ᵉ essai d’aptitude, la tension tombe à 7,5 V. Conclusion ?', c: ['Batterie à remplacer.', 'Batterie bonne.', 'Il faut encore la recharger au 1/10.'], e: 'Une 12 V ne doit pas passer sous 9 V au 3ᵉ essai : c’est le seul test qui juge vraiment la batterie.' },
      { l: L, img: A + 'alt-regulation.jpg', q: 'Circuit de charge 12 V, moteur tournant : plage de tension normale aux bornes de la batterie ?', c: ['13,5 à 15 V.', '12 à 12,6 V.', '15 à 17 V.'], e: '12 V : 13,5 à 15 V ; 24 V : 28 à 29,5 V.' },
      { l: L, img: A + 'alt-regulation.jpg', q: 'Circuit de charge 24 V, moteur tournant : plage de régulation normale ?', c: ['28 à 29,5 V.', '24 à 25 V.', '30 à 32 V.'], e: 'Au-dessus : surtension (régulateur, diode d’excitation) ; en dessous : défaut de charge.' },
      { l: L, img: A + 'alt-9d.jpg', q: 'Alternateur 24 V à 9 diodes, moteur tournant : 32 V aux bornes des batteries. Élément à incriminer ?', c: ['Une diode d’excitation (trio) et/ou le régulateur.', 'La lampe témoin.', 'Les balais usés.'], e: '1 diode trio HS = surtension ; 2 ou 3 diodes trio HS = plus de charge du tout.' },
      { l: L, img: A + 'alt-9d.jpg', q: 'Un alternateur ne possède qu’une seule borne L (D+) au régulateur. Combien de diodes a-t-il ?', c: ['9 diodes.', '6 diodes.', '12 diodes.'], e: '1 borne L = 9 diodes (6 de puissance + 3 trio) ; 2 bornes L et + = 6 ou 12 diodes, régulateur incorporé.' },
      { l: L, img: A + 'alt-rotor.jpg', q: 'Quel élément de l’alternateur reçoit le courant d’excitation ?', c: ['Le rotor (inducteur).', 'Le stator (induit).', 'Le pont de diodes.'], e: 'Rotor = inducteur, il crée le champ ; stator = induit, il produit le courant triphasé.' },
      { l: L, img: A + 'alt-porte-diodes.jpg', q: 'À l’ohmmètre, une diode du pont laisse passer le courant dans les deux sens. Elle est :', c: ['En court-circuit.', 'Coupée.', 'En bon état.'], e: 'Bonne = passe dans un seul sens ; coupée = aucun sens ; court-circuit = les deux sens.' },
      { l: L, img: 'can-support-transmission.jpg', q: 'Batterie débranchée, vous mesurez 0 Ω entre les broches 6 et 14 de la prise OBD. Conclusion ?', c: ['CAN H et CAN L sont en court-circuit.', 'Le réseau est normal.', 'Une résistance de terminaison est coupée.'], e: 'Normal : 60 Ω ; 120 Ω = une terminaison absente ou un fil coupé ; ≈ 0 Ω = H et L en court-circuit.' },
      { l: L, img: 'can-support-transmission.jpg', q: 'Entre les broches 14 et 6 de la prise OBD, vous mesurez 1,2 V. Que faites-vous ?', c: ['Réseau saturé : je débranche les calculateurs un par un jusqu’à retrouver 0,5 à 0,9 V.', 'Rien, la valeur est normale.', 'Je remplace les résistances de terminaison.'], e: 'Normal : 0,5 à 0,9 V ; 1 V ou plus = réseau saturé (interface de ligne d’un calculateur).' },
      { l: L, img: 'can-support-transmission.jpg', q: 'Bus CAN High Speed : que valent CAN H et CAN L au niveau dominant (bit 0) ?', c: ['CAN H = 3,5 V et CAN L = 1,5 V.', 'CAN H = CAN L = 2,5 V.', 'CAN H = 5 V et CAN L = 0 V.'], e: 'Dominant (0) : écart de 2 V ; récessif (1) : 2,5 V sur les deux fils.' },
      { l: L, q: 'Quel nombre binaire correspond au nombre décimal 13 ?', c: ['1101', '1011', '1110'], e: '13 = 8 + 4 + 0 + 1 → 1101.' },
      { l: L, q: 'Quel nombre décimal correspond au nombre binaire 1111 ?', c: ['15', '16', '14'], e: '8 + 4 + 2 + 1 = 15.' },
      { l: L, q: 'Dans un calculateur multiplexé, quel élément commande les actionneurs ?', c: ['L’étage de sortie.', 'L’étage d’entrée.', 'L’interface de ligne.'], e: 'Capteurs → étage d’entrée → micro-ordinateur → étage de sortie → actionneurs.' },
      { l: L, q: 'Dans un calculateur multiplexé, quel élément traduit les signaux 0–5 V et se connecte au bus ?', c: ['L’interface de ligne.', 'L’étage d’entrée.', 'Le micro-ordinateur.'], e: 'Le contrôleur de protocole construit la trame ; l’interface de ligne la met sur le bus.' },
      { l: L, img: A + 'cap-inductif.jpg', q: 'Quel signal délivre un capteur inductif ?', c: ['Une sinusoïde dont la fréquence et l’amplitude varient avec la vitesse.', 'Un signal carré d’amplitude fixe 5 V.', 'Une tension continue proportionnelle à la pression.'], e: 'Inductif = actif, non alimenté, on contrôle sa résistance. Effet Hall = carré 5 V, alimenté.' },
      { l: L, img: A + 'cap-effet-hall.jpg', q: 'Capteur passif à 3 fils (ex. effet Hall) : que trouve-t-on sur ses 3 fils ?', c: ['L’alimentation 5 V, le signal et la masse.', 'Le 12 V batterie, le CAN H et le CAN L.', 'Deux signaux et le 12 V.'], e: 'Un capteur passif doit être alimenté (99 % en 5 V).' },
      { l: L, q: 'Un actionneur est commandé en RCO à 50 % sous 12 V. Que lit le multimètre ?', c: ['6 V.', '12 V.', '0 V.'], e: 'Le multimètre ne voit que la moyenne : 50 % de 12 V = 6 V.' },
      { l: L, q: 'Alternateur piloté par bus LIN : moteur tournant, la tension reste fixe à 13,2 V. Conclusion ?', c: ['Mode secours : le bus LIN est coupé.', 'Fonctionnement normal.', 'Régulateur en surtension.'], e: 'En LIN, la tension varie de 10,7 à 16 V selon la demande ; une tension fixe de 13,2 V = mode secours.' }
    ]
  });

  /* ======================= ÉLECTRICITÉ GÉNÉRALE ======================= */
  var TR = E + 'transistor-relais.svg';
  REV.addExercises('elec', {
    lessons: [lesson(L, 'UV2 — Questions types : électricité générale', ['Saturé : Vce = 0 → toute la tension sur la charge ; Ic = β × Ib.', 'Loi des nœuds : Σ entrants = Σ sortants. Loi des mailles : Ug = somme des tensions.', 'U = V × √3 ; Ueff = Umax ÷ √2 ; f = 1 ÷ T.', '2ⁿ combinaisons pour n entrées.'], 'Ic = β·Ib · U = V·√3 · Ueff = Umax/√2', ['UR1 = Ucommande − Vbe', 'R2 = Vbe ÷ IR2', 'IR1 = Ib + IR2'], 'Convertis les mA en A avant la loi d’Ohm.')],
    questions: [
      { l: L, img: TR, q: 'Relais alimenté en 24 V, transistor saturé (Vce = 0 V), Ic = 240 mA. Résistance de la bobine RK1 ?', c: ['100 Ω', '10 Ω', '1 000 Ω'], e: 'Saturé : toute la tension est sur la bobine. RK1 = 24 / 0,24 = 100 Ω.' },
      { l: L, img: TR, q: 'Ic = 240 mA et β = 120. Courant de base Ib ?', c: ['2 mA', '20 mA', '0,2 mA'], e: 'Ib = Ic / β = 240 / 120 = 2 mA.' },
      { l: L, img: TR, q: 'Tension de commande 9 V, Vbe = 0,7 V. Tension aux bornes de la résistance de base R1 ?', c: ['8,3 V', '9,7 V', '0,7 V'], e: 'Loi des mailles : UR1 = 9 − 0,7 = 8,3 V.' },
      { l: L, img: TR, q: 'Vbe = 0,6 V et le courant dans R2 (entre base et émetteur) vaut 12 mA. Valeur de R2 ?', c: ['50 Ω', '5 Ω', '500 Ω'], e: 'R2 est en parallèle sur la jonction base-émetteur : UR2 = Vbe = 0,6 V. R2 = 0,6 / 0,012 = 50 Ω.' },
      { l: L, img: TR, q: 'Ib = 2 mA et IR2 = 20 mA. Courant IR1 dans la résistance R1 ?', c: ['22 mA', '18 mA', '20 mA'], e: 'Loi des nœuds au point base : IR1 = Ib + IR2 = 2 + 20 = 22 mA.' },
      { l: L, img: TR, q: 'UR1 = 4,4 V et IR1 = 22 mA. Valeur de R1 ?', c: ['200 Ω', '20 Ω', '2 000 Ω'], e: 'R1 = 4,4 / 0,022 = 200 Ω.' },
      { l: L, img: TR, q: 'Transistor NPN saturé : que vaut Vce et comment se comporte-t-il ?', c: ['Vce ≈ 0 V : interrupteur fermé, le relais est alimenté.', 'Vce = Ualim : interrupteur ouvert.', 'Vce = Vbe : il amplifie.'], e: 'Saturé = interrupteur fermé entre collecteur et émetteur ; bloqué (Ib = 0) = interrupteur ouvert.' },
      { l: L, img: TR, q: 'La tension de commande est coupée (Ib = 0). Que devient le relais K1 ?', c: ['Il n’est plus alimenté : le transistor est bloqué (Ic = 0).', 'Il reste alimenté.', 'Il est alimenté à moitié.'], e: 'Sans courant de base, pas de courant de collecteur : le transistor est bloqué.' },
      { l: L, img: E + 'triphase.svg', q: 'Réseau triphasé : la tension simple (phase-neutre) est de 230 V. Tension composée entre deux phases ?', c: ['400 V', '133 V', '325 V'], e: 'U = V × √3 = 230 × 1,732 ≈ 398 V ≈ 400 V.' },
      { l: L, img: E + 'triphase.svg', q: 'Réseau triphasé : 380 V entre deux phases. Tension d’un voyant branché entre une phase et le neutre ?', c: ['220 V', '658 V', '127 V'], e: 'V = U / √3 = 380 / 1,732 ≈ 220 V.' },
      { l: L, img: E + 'sinus.svg', q: 'Une tension sinusoïdale a une valeur maximale de 325 V. Valeur efficace ?', c: ['230 V', '460 V', '163 V'], e: 'Ueff = Umax / √2 = 325 / 1,414 ≈ 230 V.' },
      { l: L, img: E + 'sinus.svg', q: 'Une tension alternative a une valeur efficace de 12 V. Valeur maximale ?', c: ['17 V', '8,5 V', '24 V'], e: 'Umax = Ueff × √2 = 12 × 1,414 ≈ 17 V.' },
      { l: L, img: E + 'sinus.svg', q: 'À l’oscilloscope, la période d’un signal alternatif est T = 10 ms. Fréquence ?', c: ['100 Hz', '10 Hz', '1 000 Hz'], e: 'f = 1 / T = 1 / 0,010 = 100 Hz.' },
      { l: L, img: E + 'sinus.svg', q: 'Un signal alternatif a une fréquence de 50 Hz. Période ?', c: ['20 ms', '50 ms', '2 ms'], e: 'T = 1 / f = 1 / 50 = 0,02 s = 20 ms.' },
      { l: L, img: E + 'porte-ou-2.svg', q: 'Porte OU : A = 0 et B = 1. Sortie S ?', c: ['S = 1', 'S = 0', 'S = 2'], e: 'OU : une seule entrée à 1 suffit pour avoir S = 1.' },
      { l: L, img: E + 'porte-etnon-2.svg', q: 'Porte ET NON : A = 1 et B = 1. Sortie S ?', c: ['S = 0', 'S = 1', 'S = 2'], e: 'ET NON : S = 0 seulement si toutes les entrées sont à 1.' },
      { l: L, img: E + 'porte-ounon-2.svg', q: 'Porte OU NON : A = 0 et B = 0. Sortie S ?', c: ['S = 1', 'S = 0', 'S = 2'], e: 'OU NON : S = 1 seulement si toutes les entrées sont à 0.' },
      { l: L, img: E + 'porte-et-2.svg', q: 'Porte ET : A = 1 et B = 0. Sortie S ?', c: ['S = 0', 'S = 1', 'S = 2'], e: 'ET : S = 1 seulement si toutes les entrées sont à 1.' },
      { l: L, q: 'Nombre de combinaisons possibles d’une porte logique à 5 entrées ?', c: ['32', '10', '25'], e: '2ⁿ combinaisons : 2⁵ = 32.' },
      { l: L, q: 'Nombre de combinaisons possibles d’une porte logique à 3 entrées ?', c: ['8', '6', '9'], e: '2³ = 8.' },
      { l: L, img: E + 'noeud.svg', q: 'Au nœud N : I1 = 3 A et I2 = 2 A entrent, I3 = 1,5 A sort. Que vaut I4 ?', c: ['3,5 A', '6,5 A', '0,5 A'], e: 'Loi des nœuds : somme des courants entrants = somme des sortants → 3 + 2 = 1,5 + I4 → I4 = 3,5 A.' },
      { l: L, img: E + 'maille.svg', q: 'Ug = 24 V, UR1 = 9 V, UR3 = 5 V. Tension UR2 ?', c: ['10 V', '14 V', '38 V'], e: 'Loi des mailles : Ug = UR1 + UR2 + UR3 → UR2 = 24 − 9 − 5 = 10 V.' },
      { l: L, img: E + 'diodes-lampes.svg', q: 'Sur ce montage, quelle lampe s’allume ?', c: ['L1 seulement.', 'L2 seulement.', 'L1 et L2.'], e: 'D1 est dans le sens passant (anode vers le +) : L1 s’allume. D2 est en inverse : elle bloque, L2 reste éteinte.' },
      { l: L, img: E + 'diodes-lampes.svg', q: 'Tension aux bornes de la diode D1 (silicium) quand elle conduit ?', c: ['Environ 0,6 V', '12 V', '0 V'], e: 'Diode passante : ≈ 0,6 V (0,4 à 0,8 V) ; le reste de la tension est sur la lampe.' },
      { l: L, img: 'cah/r18.png', q: 'Combien de diodes comporte ce pont de Graëtz monophasé ?', c: ['4', '2', '6'], e: 'Pont de Graëtz = 4 diodes (double alternance) ; pont triphasé = 6 diodes.' },
      { l: L, img: 'cah/r19.png', q: 'Pont de redressement triphasé (alternateur) : combien de diodes de puissance ?', c: ['6', '3', '9'], e: '3 bras de 2 diodes : 3 positives et 3 négatives. Le 9 diodes ajoute 3 diodes d’excitation.' },
      { l: L, img: 'elec-q20-zener.png', q: 'Sur ce montage, quel est le rôle de la diode Zéner Z2 montée en inverse ?', c: ['Maintenir une tension constante (10 V) aux bornes des lampes.', 'Redresser la tension alternative.', 'Protéger contre l’inversion de polarité.'], e: 'En inverse, la Zéner garde sa tension VZ à ses bornes : elle stabilise la tension des récepteurs en parallèle.' }
    ]
  });
})();
